-- Read-only post-check for the Editions R3-R5 migrations (20270102020000 .. 20270102060000). Every row should say ok = true. Run after applying, before switching anything on.
select 'commerce is OFF' as check, coalesce((select value from public.admin_config where key = 'editions.commerce.enabled'), 'false') <> 'true' as ok;
select 'no draft package is on sale' as check, count(*) = 0 as ok from public.edition_packages where active;
select 'RLS on every Editions table' as check, count(*) = 0 as ok from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and (c.relname like 'edition%' or c.relname like 'organiser_membership%') and not c.relrowsecurity;
select 'no FOR ALL policy' as check, count(*) = 0 as ok from pg_policies where schemaname = 'public' and (tablename like 'edition%' or tablename like 'organiser_membership%') and cmd = 'ALL';
select 'anon has no write grant' as check, count(*) = 0 as ok from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and (table_name like 'edition%' or table_name like 'organiser_membership%') and privilege_type <> 'SELECT';
select 'every definer function pins search_path' as check, count(*) = 0 as ok from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prosecdef and (p.proname like 'edition%' or p.proname like 'admin_%edition%' or p.proname like 'organiser_membership%' or p.proname like 'editions%') and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%');
select 'money-in functions are not executable by people' as check, count(*) = 0 as ok from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('edition_fulfil_order','edition_order_failed','edition_refund_order','edition_payout_account_sync','edition_membership_payment_succeeded','edition_membership_payment_failed','edition_membership_subscription_changed','edition_membership_sweep','edition_participation_payment_succeeded','edition_participation_payment_failed','edition_payment_refunded','edition_payment_disputed','edition_reconcile_apply','edition_refunds_next','edition_refund_request_mark','edition_record_payment_row','edition_record_exception','edition_webhook_begin','edition_webhook_done','edition_payment_known','edition_customer_get','edition_customer_set','edition_payout_account_for','edition_email_next','edition_email_mark','edition_enqueue_email') and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'the local payment simulator is absent' as check, count(*) = 0 as ok from pg_proc where proname like 'edition_local_simulate%';
select 'the Stripe account id is not readable by people' as check, count(*) = 0 as ok from information_schema.column_privileges where table_schema = 'public' and table_name = 'edition_payout_accounts' and column_name = 'stripe_account_id' and grantee in ('anon', 'authenticated');
select 'ledger rows cannot be deleted (trigger present)' as check, count(*) = 2 as ok from pg_trigger t join pg_class c on c.oid = t.tgrelid where not t.tgisinternal and c.relname in ('edition_payments', 'edition_entitlements') and t.tgname in ('edition_payments_guard', 'edition_entitlements_append_only');
select 'no Business plan, Hub or event column changed' as check, count(*) = 0 as ok from information_schema.columns where table_schema = 'public' and table_name in ('local_businesses','local_offers','events','regular_activities','hubs','hub_members','saved_items') and column_name ~* '(edition|organiser_member)';
select 'every public partner read is gated by the eligibility predicate' as check, count(*) = 4 as ok from pg_views where schemaname = 'public' and viewname like 'edition_public_%' and definition like '%edition_participation_ok%';
select 'no money in the outbox, no address columns' as check, count(*) = 0 as ok from information_schema.columns where table_name = 'edition_email_outbox' and column_name ~* '(email|address|body|html)';
